update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Montpellier et dans l''Hérault","mecanisme":"Dans l''Hérault, une salle propre de dispositifs médicaux et une cave d''embouteillage partagent le même département et aucune contrainte commune. D''un côté la traçabilité et la propreté, de l''autre une année de récolte qui se joue en trois semaines de vendanges. Nos techniciens itinérants couvrent le bassin et se déplacent partout en France.","cta":"Demander une intervention à Montpellier","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"La remplisseuse lâche au troisième jour de vendanges. La vendange, elle, continue d''arriver au quai.","puces":[{"accroche":"Votre saison ne dure que quelques semaines.","texte":"Une panne en pleine récolte ne se rattrape pas au trimestre suivant."},{"accroche":"Le med-tech ne tolère pas l''improvisation.","texte":"Propreté, conformité, traçabilité : une intervention non documentée vaut une intervention non faite."},{"accroche":"Les entrepôts de l''axe A9 montent en automatisation.","texte":"Plus la plateforme est automatisée, plus un rouleau bloqué coûte cher."},{"accroche":"Le technicien compétent est déjà pris.","texte":"Le bassin recrute dans la santé, l''électronique et la logistique en même temps. Vos annonces attendent."},{"accroche":"Le traitement de l''eau ne connaît pas l''arrêt.","texte":"Un service public rendu en continu se fiabilise, il ne se met pas en pause."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Préventif calé sur votre saison","texte":", resserré avant les vendanges et les pics de conditionnement."},"benefice":"Les révisions tombent avant la charge, pas pendant."},{"prestation":{"accroche":"Interventions documentées","texte":"en environnement sensible : propreté, traçabilité, habilitations à jour."},"benefice":"Vos audits qualité trouvent une trace écrite pour chaque passage."},{"prestation":{"accroche":"Dépannage sur site","texte":"avec recherche de cause racine, du moteur à l''armoire électrique."},"benefice":"La ligne repart, et le défaut ne revient pas sous un autre nom."},{"prestation":{"accroche":"Automatisme et supervision","texte":"automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc."},"benefice":"Les équipements anciens retrouvent un pilotage fiable sans remplacement."},{"prestation":{"accroche":"Convoyeurs, tri et quais","texte":"des plateformes logistiques : voir notre pratique en [maintenance équipements logistiques](/secteurs/logistique/)."},"benefice":"Un seul contrat du quai de réception au quai d''expédition."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Une panne de nuit trouve un interlocuteur, pas un répondeur."},{"prestation":{"accroche":"Technicien en [Résidence](/offres/residence/)","texte":"intégré à votre équipe, prise de poste en 2 à 3 semaines."},"benefice":"Un poste ouvert depuis des mois est enfin tenu, remplacement assuré."}],"prose":[{"texte":"Pour un arrêt programmé ou un transfert de ligne, l''offre [arrêt technique](/offres/arret-technique/) se cadre de J-90 à J-30, avec restitution à la demi-journée."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le projet. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, accès, habilitations, contraintes d''hygiène ou de propreté. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, conditions horaires, matériel. Aucun surcoût découvert en fin de mission."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, puis diagnostic."},{"titre":"Compte rendu","texte":"opérations, pièces, temps passé, préconisations, versés dans votre GMAO."},{"titre":"Revue","texte":"sur contrat, suivi de la disponibilité par équipement et de la récurrence des défauts."}]},{"type":"garanties","puces":[{"accroche":"Le profil est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation partagés. Vous savez qui entre en salle propre."},{"accroche":"Le périmètre et la sortie sont écrits.","texte":"Ce qui est inclus, ce qui ne l''est pas, les conditions d''astreinte, les modalités d''arrêt du contrat."},{"accroche":"Chaque passage laisse une trace exploitable.","texte":"Historique machine à jour dans votre outil, préconisations chiffrées, confidentialité respectée."}]},{"type":"cta","question":"Besoin de passer la prochaine saison sans arrêt subi ?","bouton":"Demander une intervention à Montpellier","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Renfort de 6 mois sur un site de traitement des eaux industrielles à risque chimique","texte":", avec habilitation dédiée","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"2 techniciens en 3x8 sur des lignes de nutrition infantile","texte":", liquides et conditionnement poudre","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"6 techniciens polyvalents en permanence sur un contrat de préventif annuel","texte":", prise en charge complète en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"1 à 3 techniciens en renfort permanent sur plusieurs sites de production","texte":", depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment dans l''Hérault, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence à Montpellier et nous ne l''inventons pas : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et le chargé d''affaires vous dit franchement si le besoin est tenable."},{"question":"Quelles villes couvrez-vous autour de Montpellier ?","reponse":"Montpellier et Lattes, Sète, Béziers, Nîmes et Alès, avec les zones d''activité de l''axe A9. Au-delà, nos techniciens se déplacent partout en France."},{"question":"Pouvez-vous intervenir pendant les vendanges, sur une fenêtre très courte ?","reponse":"Oui, à condition de préparer. Le préventif se resserre avant la saison et les pièces critiques sont identifiées en amont. L''astreinte couvre la période de charge si le contrat la prévoit."},{"question":"Vos techniciens travaillent-ils en environnement pharmaceutique ou med-tech ?","reponse":"Oui, avec les habilitations et les règles du site. Chaque intervention est documentée, propreté et traçabilité comprises. Le point se fait à la qualification, jamais une fois sur place."},{"question":"Pouvez-vous reprendre notre contrat de maintenance actuel ?","reponse":"Oui. Reprise de l''historique, connexion à vos données d''arrêt, phase de recouvrement avec le prestataire sortant. Si un contrat vous lie encore, un périmètre d''essai permet de comparer sur des faits."},{"question":"Travaillez-vous dans notre GMAO ?","reponse":"Oui. Chaque intervention y est saisie : temps passé, pièces, préconisations, historique par machine. Pas de système parallèle, pas de double saisie. Vos données vous appartiennent."}]},{"type":"ctaFinal","question":"Besoin de savoir où votre site perd réellement de la disponibilité ?","bouton":"Demander une intervention à Montpellier","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-montpellier/';
